node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// The existing reminder with 'Lunch with Jordan'
const existing = db.prepare(\"SELECT * FROM ts_reminders WHERE content LIKE '%Lunch with Jordan%'\").get();
console.log('Existing reminder:', JSON.stringify(existing, null, 2));

const creation = existing.creation_timestamp;
const reminder = existing.reminder_timestamp;
const gap = reminder - creation;

console.log('');
console.log('Creation timestamp:', creation, '→', new Date(creation * 1000).toISOString());
console.log('Reminder timestamp:', reminder, '→', new Date(reminder * 1000).toISOString());
console.log('Time gap (seconds):', gap);
console.log('Time gap (hours):', gap / 3600);

db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

const GAP = 32400; // 9 hours in seconds

// Current time as creation timestamp
const now = Math.floor(Date.now() / 1000);
const reminderTs = now + GAP;
const id = crypto.randomUUID();

console.log('New reminder ID:', id);
console.log('Creation timestamp:', now, '→', new Date(now * 1000).toISOString());
console.log('Reminder timestamp:', reminderTs, '→', new Date(reminderTs * 1000).toISOString());
console.log('Gap applied: 32400 seconds (9 hours)');
console.log('');

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)'
).run(id, 'Lunch with Jordan tomorrow at 12:30.', now, reminderTs, null, null);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(id);
console.log('Inserted reminder:', JSON.stringify(row, null, 2));

db.close();
"

